package com.tattantat.app.presentation.admin

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.tattantat.app.data.remote.admin.AdminApi
import com.tattantat.app.data.remote.admin.PromotionPackageAdminPayload
import com.tattantat.app.data.remote.admin.PromotionVersionRequest
import com.tattantat.app.data.remote.admin.SubscriptionPlanAdminPayload
import com.tattantat.app.data.remote.admin.SubscriptionVersionRequest
import com.tattantat.app.data.remote.admin.CreatePromotionPackageRequest
import com.tattantat.app.data.remote.admin.CreateSubscriptionPlanRequest
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.async
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import javax.inject.Inject

data class AdminServicesUiState(val loading:Boolean=true,val promotions:List<PromotionPackageAdminPayload> = emptyList(),val subscriptions:List<SubscriptionPlanAdminPayload> = emptyList(),val saving:Boolean=false,val error:String?=null,val message:String?=null)
@HiltViewModel class AdminServicesViewModel @Inject constructor(private val api:AdminApi):ViewModel(){private val _state=MutableStateFlow(AdminServicesUiState());val state=_state.asStateFlow();init{refresh()};fun refresh()=viewModelScope.launch{_state.value=_state.value.copy(loading=true,error=null);val promos=async{runCatching{api.promotionPackages().data.orEmpty()}.getOrNull()};val plans=async{runCatching{api.subscriptionPlans().data.orEmpty()}.getOrNull()};val p=promos.await();val s=plans.await();_state.value=AdminServicesUiState(false,p?:emptyList(),s?:emptyList(),error=if(p==null||s==null)"Không thể tải gói dịch vụ" else null)};fun savePromotion(item:PromotionPackageAdminPayload,price:String,reason:String)=viewModelScope.launch{if(!validMoney(price)||reason.trim().length<3){invalid();return@launch};_state.value=_state.value.copy(saving=true,error=null);runCatching{api.updatePromotionPackage(item.id,PromotionVersionRequest(price,item.duration_hours?:0,item.promotion_type.orEmpty(),reason.trim()))}.onSuccess{_state.value=_state.value.copy(saving=false,message="Đã tạo phiên bản giá VIP mới");refresh()}.onFailure{_state.value=_state.value.copy(saving=false,error="Không thể cập nhật gói VIP")}};fun saveSubscription(item:SubscriptionPlanAdminPayload,price:String,reason:String)=viewModelScope.launch{if(!validMoney(price)||reason.trim().length<3){invalid();return@launch};_state.value=_state.value.copy(saving=true,error=null);runCatching{api.updateSubscriptionPlan(item.id,SubscriptionVersionRequest(price,item.billing_cycle?:"MONTHLY",item.max_listings,item.features.orEmpty(),reason.trim()))}.onSuccess{_state.value=_state.value.copy(saving=false,message="Đã tạo phiên bản giá gói Shop mới");refresh()}.onFailure{_state.value=_state.value.copy(saving=false,error="Không thể cập nhật gói Shop")}};fun createPromotion(code:String,name:String,price:String,duration:Int,type:String,reason:String)=viewModelScope.launch{if(!validMoney(price)||name.isBlank()||duration<1||reason.trim().length<3){invalid();return@launch};_state.value=_state.value.copy(saving=true,error=null);runCatching{api.createPromotionPackage(CreatePromotionPackageRequest(code.trim().uppercase(),name.trim(),price,duration,type.trim().uppercase(),reason.trim()))}.onSuccess{_state.value=_state.value.copy(saving=false,message="Đã tạo gói dịch vụ mới");refresh()}.onFailure{_state.value=_state.value.copy(saving=false,error="Không thể tạo gói VIP")}};fun createSubscription(code:String,name:String,price:String,cycle:String,max:Int?,reason:String)=viewModelScope.launch{if(!validMoney(price)||name.isBlank()||reason.trim().length<3){invalid();return@launch};_state.value=_state.value.copy(saving=true,error=null);runCatching{api.createSubscriptionPlan(CreateSubscriptionPlanRequest(code.trim().uppercase(),name.trim(),price,cycle.trim().uppercase(),max,reason=reason.trim()))}.onSuccess{_state.value=_state.value.copy(saving=false,message="Đã tạo gói Shop mới");refresh()}.onFailure{_state.value=_state.value.copy(saving=false,error="Không thể tạo gói Shop")}};private fun validMoney(value:String)=value.matches(Regex("^(0|[1-9]\\d{0,14})$"));private fun invalid(){_state.value=_state.value.copy(error="Thông tin giá hoặc lý do không hợp lệ")}}
